/// Routes of [`OWNER_ROUTES`] that EVERY paired device (phone or desktop) may
/// still call without being the owner's administrator: what a device does for
/// the owner every day. Everything else in [`OWNER_ROUTES`] is refused to a
/// paired peer (see [`peer_may_call`]) unless it is the administrator desktop
/// of a host, which is the owner (`peer.rs`, `admin_desktop_never`).
///
/// * deciding an approval or a question (audited as `peer.decision_requested`);
/// * the screen takeover buttons (the live-view grants decide, not this table);
/// * timers (the handlers refuse triggers and prechecks from a peer).
pub const PEER_OK_ROUTES: &[(&str, &str)] = &[
    ("POST", "/v1/approvals/{}"),
    ("POST", "/v1/questions/{}"),
    ("POST", "/v1/control/{}"),
    ("POST", "/v1/control/takeover"),
    ("POST", "/v1/control/override"),
    ("POST", "/v1/control/recover"),
    ("POST", "/v1/control/release"),
    ("POST", "/v1/schedules"),
    ("PUT", "/v1/schedules/{}"),
    ("DELETE", "/v1/schedules/{}"),
    ("POST", "/v1/schedules/{}/run-now"),
    ("POST", "/v1/schedules/{}/occurrences/{}/retry"),
    ("POST", "/v1/schedules/{}/reclaim"),
    // Pairing and who leads, on a daemon that is not an always-on host (a phone may manage
    // ownership there; the handlers decide what each role may do). On a HOST no peer reaches
    // any of these: `peer::guard` refuses every `/v1/host` write to every paired device.
    ("POST", "/v1/host/invite"),
    ("DELETE", "/v1/host/devices/{}"),
    ("PUT", "/v1/host/devices/{}/admin"),
    ("POST", "/v1/host/standby"),
    ("POST", "/v1/host/activate"),
    ("POST", "/v1/host/update"),
];

/// Further [`OWNER_ROUTES`] that a paired DESKTOP (not a phone) may call without
/// administration, because the desktop of a person acts for them there: recorded
/// workflows, local components, the Composio connections and reading the mail
/// channel. These were never closed to a desktop; the table only writes it down.
pub const PEER_OK_DESKTOP_ROUTES: &[(&str, &str)] = &[
    ("POST", "/v1/runs/{}/workflow-proposal"),
    ("POST", "/v1/workflows"),
    ("DELETE", "/v1/workflows/{}"),
    ("POST", "/v1/workflows/{}/run"),
    ("GET", "/v1/workflows"),
    ("GET", "/v1/workflows/{}"),
    ("POST", "/v1/components/{}/install"),
    ("GET", "/v1/email/channel"),
    ("GET", "/v1/email/channel/replies"),
    ("GET", "/v1/email/accounts/{}/messages"),
    ("PUT", "/v1/composio/key"),
    ("DELETE", "/v1/composio/key"),
    ("POST", "/v1/composio/login"),
    ("DELETE", "/v1/composio/apps/{}"),
    ("POST", "/v1/composio/apps/{}/connect"),
    ("PUT", "/v1/composio/apps/{}/enabled"),
];

fn pattern_matches(pattern: &str, path: &str) -> bool {
    let mut want = pattern.split('/');
    let mut have = path.split('/');
    loop {
        match (want.next(), have.next()) {
            (Some("*"), Some(rest)) => return !rest.is_empty(),
            (Some("{}"), Some(seg)) if !seg.is_empty() => {}
            (Some(w), Some(h)) if w == h => {}
            (None, None) => return true,
            _ => return false,
        }
    }
}

fn in_table(table: &[(&str, &str)], method: &str, path: &str) -> bool {
    let path = path
        .strip_suffix('/')
        .filter(|p| !p.is_empty())
        .unwrap_or(path);
    table
        .iter()
        .any(|(m, pattern)| m.eq_ignore_ascii_case(method) && pattern_matches(pattern, path))
}

/// Whether `method path` needs the owner key.
#[must_use]
pub fn is_owner_route(method: &str, path: &str) -> bool {
    // The CLI passes a query string; the server matches the bare path.
    let path = path.split_once('?').map_or(path, |(p, _)| p);
    let decoded = percent_encoding::percent_decode_str(path)
        .decode_utf8()
        .map_or_else(|_| path.to_owned(), std::borrow::Cow::into_owned);
    let mut collapsed = String::with_capacity(decoded.len());
    for ch in decoded.chars() {
        if !(ch == '/' && collapsed.ends_with('/')) {
            collapsed.push(ch);
        }
    }
    in_table(OWNER_ROUTES, method, path) || in_table(OWNER_ROUTES, method, &collapsed)
}

/// Whether the table lists `method path` as an ordinary token route.
#[must_use]
pub fn is_token_ok_route(method: &str, path: &str) -> bool {
    in_table(TOKEN_OK_ROUTES, method, path)
}

/// Whether a paired device that is NOT the owner's administrator desktop may
/// call `method path` although it is an owner route (see [`PEER_OK_ROUTES`]).
/// A path that is not an owner route is not this function's business: it
/// returns `true`.
#[must_use]
pub(crate) fn peer_may_call(role: crate::PeerRole, method: &str, path: &str) -> bool {
    if !is_owner_route(method, path) {
        return true;
    }
    let path = path.split_once('?').map_or(path, |(p, _)| p);
    in_table(PEER_OK_ROUTES, method, path)
        || (role == crate::PeerRole::Desktop && in_table(PEER_OK_DESKTOP_ROUTES, method, path))
}

/// The one guard of every owner route: runs after bearer authentication on the
/// local router, so a request that reaches a handler of an owner route has
/// presented the owner key. The handlers do not repeat the check.
pub(crate) async fn owner_gate(State(s): State<AppState>, req: Request, next: Next) -> Response {
    if req.extensions().get::<crate::PeerIdentity>().is_none()
        && is_owner_route(req.method().as_str(), req.uri().path())
        && let Err(e) = s.require_owner(req.headers())
    {
        return e.into_response();
    }
    next.run(req).await
}

/// Whether a bot profile edit changes what the bot may do without asking: the
/// permission preset and levels, the tool lists, file access, the computer the
/// bot works on (`runtime.computer`: this PC, the host, a paired server) or a
/// switch to an external CLI engine. Such an edit needs the owner key even though plain
/// profile edits (name, persona, model choice) do not.
#[must_use]
pub fn execution_changed(current: Option<&serde_json::Value>, next: &serde_json::Value) -> bool {
    let cli_executor = |v: &serde_json::Value| {
        v.pointer("/models/executor")
            .and_then(serde_json::Value::as_str)
            .filter(|e| e.starts_with("cli:"))
            .map(str::to_owned)
    };
    ["permissions", "tools", "files", "runtime", "delegation"]
        .iter()
        .any(|k| next.get(k).is_some() && next.get(k) != current.and_then(|c| c.get(k)))
        || cli_executor(next) != current.and_then(cli_executor)
}

impl AppState {
    /// The owner key of this daemon, for its own in-process clients (the
    /// Telegram channel decides approvals for the owner's chat). Never logged.
    #[must_use]
    pub fn owner_key(&self) -> Option<String> {
        self.0.owner_key.get().cloned()
    }

    /// Whether `headers` carry the owner key (for handler-level checks of
    /// edits that are only sometimes owner-only).
    pub(crate) fn has_owner(&self, headers: &HeaderMap) -> bool {
        self.owner_ok(headers)
    }
}
